<script>
document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.split-report .sr-kpi-note').forEach(function (note) {
        if (note.textContent.trim() === 'Base payment + service charge') {
            note.textContent = 'Total charged to the payer';
        }
    });
    const trend = @json($chartTrend), statuses = @json($chartStatus), services = @json($chartServices);
    const money = value => '₦' + Number(value || 0).toLocaleString('en-NG', {minimumFractionDigits:2, maximumFractionDigits:2});
    const colors = ['#1769aa','#22a06b','#e2a52e','#7954bd','#d25472','#1e9ca8'];
    const makeChart = (id, config, emptyId, hasData) => { const canvas = document.getElementById(id), empty = document.getElementById(emptyId); if (!hasData) { canvas?.classList.add('d-none'); empty?.classList.remove('d-none'); } else if (window.Chart && canvas) new Chart(canvas, config); };
    makeChart('collectionTrendChart', {type:'line', data:{labels:trend.map(x=>x.label), datasets:[{label:'Gross billed',data:trend.map(x=>x.gross),borderColor:'#1769aa',backgroundColor:'rgba(23,105,170,.12)',fill:true,tension:.35,pointRadius:3},{label:'Service charge',data:trend.map(x=>x.charge),borderColor:'#22a06b',backgroundColor:'transparent',fill:false,tension:.35,pointRadius:3}]}, options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom',labels:{usePointStyle:true}},tooltip:{callbacks:{label:ctx=>ctx.dataset.label+': '+money(ctx.raw)}}},scales:{y:{beginAtZero:true,ticks:{callback:value=>money(value)}},x:{grid:{display:false}}}}}, 'trendEmpty', trend.length > 0);
    makeChart('statusChart', {type:'doughnut', data:{labels:statuses.map(x=>x.label),datasets:[{data:statuses.map(x=>x.amount),backgroundColor:colors,borderWidth:3,borderColor:'#fff'}]}, options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true}},tooltip:{callbacks:{label:ctx=>ctx.label+': '+money(ctx.raw)}}}}}, 'statusEmpty', statuses.length > 0);
    makeChart('serviceChart', {type:'bar', data:{labels:services.map(x=>x.label),datasets:[{label:'Gross billed',data:services.map(x=>x.amount),backgroundColor:'#2a91c4',borderRadius:7,maxBarThickness:30}]}, options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>money(ctx.raw)}}},scales:{x:{beginAtZero:true,ticks:{callback:value=>money(value)}},y:{grid:{display:false}}}}}, 'serviceEmpty', services.length > 0);
    const toggle = document.getElementById('filter-toggle'), body = document.getElementById('filter-body'), chevron = document.querySelector('.sr-chevron'); const toggleFilters = () => { const collapsed = body.classList.toggle('is-collapsed'); chevron.classList.toggle('is-open', !collapsed); toggle.setAttribute('aria-expanded', String(!collapsed)); }; toggle?.addEventListener('click', event => { if (event.target.closest('a')) return; toggleFilters(); }); toggle?.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggleFilters(); } });
    const period = document.getElementById('report-period'), dates = document.querySelectorAll('.custom-date'), refreshDates = () => dates.forEach(field => field.style.display = period.value === 'custom' ? '' : 'none'); period?.addEventListener('change', refreshDates); refreshDates();
    const faculty = document.getElementById('report-faculty'), department = document.getElementById('report-department'), program = document.getElementById('report-program'); const filterOptions = (select, attrs, values) => Array.from(select.options).forEach(option => { if (!option.value) { option.hidden = false; return; } option.hidden = attrs.some((attr,index) => values[index] && option.dataset[attr] !== values[index]); if (option.hidden && option.selected) { option.selected = false; select.value = ''; } }); const cascade = () => { if (faculty && department && program) { filterOptions(department,['faculty'],[faculty.value]); filterOptions(program,['faculty','department'],[faculty.value,department.value]); } }; faculty?.addEventListener('change', cascade); department?.addEventListener('change', cascade); cascade();
});
</script>
